def smallestEquivalent(a, b, base):
    parent = list(range(26))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in zip(a, b):
        ru, rv = find(ord(u) - 97), find(ord(v) - 97)
        if ru != rv:
            if ru < rv:
                parent[rv] = ru
            else:
                parent[ru] = rv
    return "".join(chr(97 + find(ord(c) - 97)) for c in base)
